import 'package:riverpod_annotation/riverpod_annotation.dart';

import '../features/room/models/conversation.dart';
import '../features/today/models/today_card_model.dart';
import '../shared/api/mock_data.dart';
import '../shared/models/message.dart';
import '../shared/models/room.dart';
import '../shared/models/skill_info.dart';

// Generated by riverpod_generator. Will be created by `dart run build_runner build`
// on the Mac. The file does not exist on Linux.
part 'app_state.g.dart';

/// Auth state — true once the user has tapped through passkey or magic link.
@riverpod
class AuthController extends _$AuthController {
  @override
  bool build() => false;

  void signIn() => state = true;

  void signOut() => state = false;
}

/// Rooms — list of all rooms visible in the drawer. Hardcoded for v1.
@riverpod
List<Room> rooms(Ref ref) => MockData.rooms;

/// Currently active room. Defaults to Claw Main.
@riverpod
class ActiveRoom extends _$ActiveRoom {
  @override
  Room build() => MockData.activeRoom;

  void setActive(String roomId) {
    final next = MockData.roomById(roomId);
    if (next != null && next.isActive) {
      state = next;
    }
  }
}

/// Today cards. Replace with `/api/today/cards` in PR2.
@riverpod
List<TodayCard> todayCards(Ref ref) => MockData.todayCards;

/// Active conversation messages for the current room.
@riverpod
class ActiveConversation extends _$ActiveConversation {
  @override
  List<Message> build() => MockData.activeMessages;

  void appendUserMessage(String body) {
    final message = Message(
      id: 'msg-${DateTime.now().microsecondsSinceEpoch}',
      role: MessageRole.user,
      body: body,
      timestamp: DateTime.now(),
    );
    state = [...state, message];
    // TODO(backend): post message to gateway and stream assistant response.
  }
}

/// Skills loaded into the active room. Read-only in v1.
@riverpod
List<SkillInfo> roomSkills(Ref ref) => MockData.clawMainSkills;

/// History — past conversations for the active room, grouped date-wise in the UI.
@riverpod
List<Conversation> roomHistory(Ref ref) => MockData.history;
